"""Original stoichiometry, experimental rate and equilibrium practice."""
import math
from decimal import Decimal
from common import Bank,p,step,f,v,quantity as u,svg,text,line,graph
B=Bank('R2','reactivity-2',{'R2.1':'How much? The amount of chemical change','R2.2':'How fast? The rate of chemical change','R2.3':'How far? The extent of chemical change'})
R=8.31
def table(headers,rows):return '| '+' | '.join(headers)+' |\n|'+'|'.join(['---']*len(headers))+'|\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in rows)
def chem(s):return r'$\mathrm{'+s+'}$'
def profile(reactant,product,peak,cat):
    low=min(reactant,product)-15;high=peak+25
    Y=lambda e:305-(e-low)/(high-low)*235
    z=text(400,25,'Two pathways for the same reaction',18)+text(85,52,'Relative enthalpy / kJ mol⁻¹',14,'start')
    z+=line(85,310,750,310,arrow=True)+line(85,310,85,60,arrow=True)+text(420,365,'Reaction coordinate (schematic)',15)
    for energy,x,label in [(reactant,175,'reactants'),(product,665,'products'),(peak,390,'uncatalysed'),(cat,445,'catalysed')]:
        z+=line(85,Y(energy),740,Y(energy),'#e7ecf0',1)
        z+=text(70,Y(energy)+4,f(energy),13,'end')
        z+=text(x,Y(energy)-12,label,13)
    for energy,colour in [(peak,'#9d393e'),(cat,'#237e9b')]:
        path=f'M 130 {Y(reactant):.3f} L 215 {Y(reactant):.3f} C 275 {Y(reactant):.3f}, 300 {Y(energy):.3f}, 390 {Y(energy):.3f} C 480 {Y(energy):.3f}, 515 {Y(product):.3f}, 585 {Y(product):.3f} L 710 {Y(product):.3f}'
        z+=f'<path d="{path}" fill="none" stroke="{colour}" stroke-width="2.5"/>'
    return svg(z)

# R2.1: eight distinct shared stoichiometric task families.
for mass in [3.2,4.8,6.4,8.0]:
    product=mass/64*80
    B.add('R2.1','sl','easy','Copper oxide from a measured copper mass',r'$\mathrm{2Cu(s)+O_2(g)\to2CuO(s)}$'+f'. Oxygen is in excess and {u(mass,"g")} of copper reacts completely. Use molar masses '+u(64,r'g\,mol^{-1}')+' for copper and '+u(80,r'g\,mol^{-1}')+' for copper(II) oxide. What mass of oxide forms?',correct=u(product,'g'),distractors=[u(product/2,'g'),u(product*2,'g'),u(mass+16,'g')],reasoning='Copper and copper(II) oxide have a 1:1 mole ratio; multiply the copper amount by the oxide molar mass.')
for mass,V,c in [(.48,50,.50),(.36,40,1.0),(.72,60,.8),(.60,80,.5)]:
    nmg=mass/24.0;nhcl=V*c/1000;extent=min(nmg,nhcl/2);leftmg=nmg-extent;lefthcl=nhcl-2*extent
    B.add('R2.1','sl','medium','Identifying a limiting reagent',f'A {u(mass,"g")} magnesium sample reacts with {u(V,"cm^3")} of hydrochloric acid of concentration '+u(c,r'mol\,dm^{-3}')+r'. The equation is $\mathrm{Mg+2HCl\to MgCl_2+H_2}$. Use '+u(24.0,r'g\,mol^{-1}')+' for magnesium.',parts=[p('Identify the limiting reagent, showing your calculation.',step('Initial amounts: magnesium '+u(nmg,'mol')+' and hydrogen chloride '+u(nhcl,'mol')+'.','M1'),step(('Hydrogen chloride is limiting: compare its amount divided by two with the magnesium amount.' if nhcl/2<nmg else 'Magnesium is limiting: its amount is less than half the hydrogen chloride amount.'),'R1')),p('Determine the amount of hydrogen produced and the amount of excess reagent left.',step('The hydrogen amount is '+u(extent,'mol')+'.'),step(('Magnesium remaining: '+u(leftmg,'mol')+'.' if leftmg>0 else 'Hydrogen chloride remaining: '+u(lefthcl,'mol')+'.')))])
for mco,actual in [(5.6,4.8),(8.4,7.2),(11.2,9.0),(14.0,12.0)]:
    theoretical=mco/28*32;yieldp=100*actual/theoretical
    B.add('R2.1','sl','medium','Percentage yield of methanol',r'$\mathrm{CO(g)+2H_2(g)\to CH_3OH(g)}$'+f'. In a model production trial, {u(mco,"g")} of carbon monoxide is supplied with excess hydrogen. The collected methanol mass is {u(actual,"g")}. Use molar masses '+u(28,r'g\,mol^{-1}')+' and '+u(32,r'g\,mol^{-1}')+' for carbon monoxide and methanol respectively.',parts=[p('Calculate the theoretical methanol mass and percentage yield.',step('The 1:1 mole ratio gives a theoretical mass of '+u(theoretical,'g')+'.','M1'),step(r'$\%\mathrm{yield}=m_{\mathrm{actual}}/m_{\mathrm{theoretical}}\times100$.','M1'),step('The yield is '+u(yieldp,r'\%')+'.')),p('Suggest one reason the collected yield may be below 100% even when carbon monoxide is the limiting reagent.',step('Accept incomplete conversion, competing reactions, or product losses during separation/transfer. The limiting-reagent calculation alone does not guarantee complete recovery.','R1'))])
for equation,target,masses in [(r'$\mathrm{C_2H_4+H_2O\to C_2H_5OH}$','ethanol',[28,18,46]),(r'$\mathrm{C_2H_5Br+NaOH\to C_2H_5OH+NaBr}$','ethanol',[109,40,46]),(r'$\mathrm{C_2H_5OH+O_2\to CH_3COOH+H_2O}$','ethanoic acid',[46,32,60]),(r'$\mathrm{CH_3COOH+C_2H_5OH\to CH_3COOC_2H_5+H_2O}$','ethyl ethanoate',[60,46,88])]:
    m1,m2,desired=masses;ae=100*desired/(m1+m2)
    B.add('R2.1','sl','medium','Atom economy of a synthetic route','The target product is '+target+' in the equation '+equation+'. Molar masses of the two reactants are '+u(m1,r'g\,mol^{-1}')+' and '+u(m2,r'g\,mol^{-1}')+'; the target product has molar mass '+u(desired,r'g\,mol^{-1}')+'. What is the atom economy for forming the target product?',correct=u(ae,r'\%'),distractors=[u(100*desired/m1,r'\%'),u(100*desired/m2,r'\%'),u(100*(m1+m2-desired)/(m1+m2),r'\%')],reasoning='With every coefficient equal to one, atom economy is target-product molar mass divided by the sum of reactant molar masses, multiplied by 100.')
for acidV,cbase,titres in [(25,.100,[24.8,24.9,24.9]),(20,.120,[18.6,18.5,18.6]),(25,.080,[22.3,22.4,22.3]),(15,.150,[16.1,16.0,16.1])]:
    mean=sum(titres)/3;ca=cbase*mean/(2*acidV)
    B.add('R2.1','sl','hard','Concordant acid–base titration data',f'In a constructed titration, {u(acidV,"cm^3")} aliquots of sulfuric acid are titrated with sodium hydroxide of concentration '+u(cbase,r'mol\,dm^{-3}')+r'. Use complete neutralization: $\mathrm{H_2SO_4+2NaOH\to Na_2SO_4+2H_2O}$. All three concordant titres below are to be included.'+'\n\n'+table(['Trial',r'Titre / $\mathrm{cm^3}$'],[(j+1,t) for j,t in enumerate(titres)]),question_type='data-based',parts=[p('Calculate the mean titre and the acid concentration.',step('The mean titre is '+u(mean,r'cm^3')+'.'),step('Amount of sodium hydroxide is '+u(cbase*mean/1000,'mol')+'; divide by two for sulfuric acid.','M1'),step('Divide by the acid volume in cubic decimetres.','M1'),step('The sulfuric acid concentration is '+u(ca,r'mol\,dm^{-3}')+'.')),p('Explain why the burette should be rinsed with titrant rather than left containing residual water.',step('Residual water would dilute the titrant, so the concentration delivered would not be the stated value.','R1'))])
for C,H,O,emp,emass,M,molecular in [(40.00,6.67,53.33,'CH_2O',30,180,'C_6H_{12}O_6'),(52.17,13.04,34.79,'C_2H_6O',46,46,'C_2H_6O'),(54.55,9.09,36.36,'C_2H_4O',44,88,'C_4H_8O_2'),(64.86,13.51,21.63,'C_4H_{10}O',74,74,'C_4H_{10}O')]:
    B.add('R2.1','sl','hard','Formula from percentage composition',f'A constructed elemental analysis of a compound gives {C:.2f}% carbon, {H:.2f}% hydrogen and {O:.2f}% oxygen by mass. Its molar mass is '+u(M,r'g\,mol^{-1}')+'. Use relative atomic masses C12.0, H1.0 and O16.0; recognize the nearest small whole-number ratio within rounding of the percentages.',parts=[p('Determine the empirical formula.',step('For a 100 g sample, divide each mass by its relative atomic mass.','M1'),step('Reduce the amounts to the nearest small whole-number ratio, giving '+chem(emp)+'.')),p('Determine the molecular formula.',step('The empirical formula mass is '+u(emass,r'g\,mol^{-1}')+' and the molecular multiplier is '+str(M//emass)+'.','M1'),step('The molecular formula is '+chem(molecular)+'.'))])
for salt,M,mass in [('CaCO_3',100,2.50),('MgCO_3',84,2.10),('SrCO_3',148,3.70),('BaCO_3',197,4.925)]:
    n=mass/M;V=float(Decimal(str(mass))/Decimal(str(M))*Decimal("22.7"))
    B.add('R2.1','sl','medium','Carbon dioxide from a carbonate',f'A {u(mass,"g",sig=5)} sample of '+chem(salt)+' reacts completely with excess hydrochloric acid, giving one mole of carbon dioxide per mole of carbonate. Use molar mass '+u(M,r'g\,mol^{-1}')+' for the carbonate and gas molar volume '+u(22.7,r'dm^3\,mol^{-1}')+' at the stated collection conditions. What volume of dry carbon dioxide forms?',correct=u(V,r'dm^3'),distractors=[u(V*2,r'dm^3'),u(V/2,r'dm^3'),u(V*1000,r'dm^3')],reasoning='The amount of carbonate, and hence carbon dioxide, is '+u(n,'mol')+'. Multiply by the supplied molar gas volume.')
for formula,c,h,amount,M in [('C_2H_6',2,6,.05,30),('C_3H_8',3,8,.02,44),('C_2H_4',2,4,.04,28),('C_4H_{10}',4,10,.01,58)]:
    mco2=44*c*amount;mwater=18*h*amount/2
    B.add('R2.1','sl','hard','Combustion analysis of a hydrocarbon','Complete combustion of a hydrocarbon sample produces '+u(mco2,'g',sig=5)+' of carbon dioxide and '+u(mwater,'g',sig=5)+' of water. Its independently measured molar mass is '+u(M,r'g\,mol^{-1}')+'. Use C12.0, H1.0 and O16.0.',question_type='data-based',parts=[p('Determine the amounts of carbon atoms and hydrogen atoms in the original sample.',step('Carbon amount equals the carbon dioxide amount: '+u(c*amount,'mol')+'.','M1'),step('Hydrogen-atom amount is twice the water amount: '+u(h*amount,'mol')+'.')),p('Determine the empirical and molecular formulas.',step('The empirical formula is '+chem('C'+('_'+str(c//math.gcd(c,h)) if c//math.gcd(c,h)>1 else '')+'H'+('_{'+str(h//math.gcd(c,h))+'}' if h//math.gcd(c,h)>1 else ''))+'; the molecular multiplier is '+str(math.gcd(c,h))+'.','M1'),step('Use the empirical formula mass and supplied molar mass to obtain '+chem(formula)+'.'))])

# R2.2: shared rate concepts and profiles, then experimentally supported HL models.
for initial,final,t in [(.80,.50,30),(.60,.25,50),(.90,.45,75),(.75,.30,60)]:
    rate=(initial-final)/t
    B.add('R2.2','sl','easy','Average disappearance rate',f'A reactant concentration falls from '+u(initial,r'mol\,dm^{-3}')+' to '+u(final,r'mol\,dm^{-3}')+f' in {u(t,"s")}. What is its positive average rate of disappearance?',correct=u(rate,r'mol\,dm^{-3}\,s^{-1}'),distractors=[u(-rate,r'mol\,dm^{-3}\,s^{-1}'),u((initial+final)/t,r'mol\,dm^{-3}\,s^{-1}'),u(rate*t*t,r'mol\,dm^{-3}\,s^{-1}')],reasoning='The positive disappearance rate is the concentration decrease divided by the elapsed time.')
for rate in [.004,.006,.008,.012]:
    B.add('R2.2','sl','medium','Rates and equation coefficients',r'For $\mathrm{2H_2O_2(aq)\to2H_2O(l)+O_2(g)}$, the positive rate of disappearance of hydrogen peroxide is '+u(rate,r'mol\,dm^{-3}\,s^{-1}')+'. What is the corresponding rate of oxygen formation per unit reaction volume?',correct=u(rate/2,r'mol\,dm^{-3}\,s^{-1}'),distractors=[u(rate*2,r'mol\,dm^{-3}\,s^{-1}'),u(rate,r'mol\,dm^{-3}\,s^{-1}'),u(-rate/2,r'mol\,dm^{-3}\,s^{-1}')],reasoning='Two moles of hydrogen peroxide disappear for each mole of oxygen formed, so the oxygen formation rate is half the disappearance rate.')
collision=[('Why does increasing temperature usually increase the rate of a reaction with an activation-energy barrier?','A larger fraction of collisions has enough energy to overcome the barrier.',['The activation energy of the uncatalysed pathway must fall.','All particles acquire exactly the same energy.','Every collision becomes successful regardless of orientation.'],'The energy distribution changes, increasing the fraction above the activation energy.'),('A powdered solid reacts faster than an equal mass of larger pieces under otherwise identical conditions. Why?','Its greater exposed surface area allows more reactant collisions at the solid surface.',['Its atoms have acquired a different relative atomic mass.','The reaction enthalpy must have doubled.','Its equilibrium constant must increase.'],'More exposed reactive surface raises collision opportunities without requiring a new reaction enthalpy.'),('Increasing the concentration of a reacting solute can increase the reaction rate. Which collision-theory explanation is appropriate?','More reacting particles per unit volume can increase the frequency of collisions.',['The solute particles become larger.','Every collision automatically has higher energy.','The activation barrier is removed.'],'At fixed temperature the key change is collision frequency, not an obligatory change in collision energy.'),('What is a sound explanation of catalyst action?','A catalyst supplies an alternative mechanism with a lower activation-energy barrier.',['It changes the equilibrium constant at fixed temperature.','It makes the reaction enthalpy more negative.','It permanently supplies the energy used in every reaction event.'],'A catalyst changes the pathway and speeds approach to equilibrium without changing the thermodynamic equilibrium constant.')]
for stem,good,bad,why in collision:B.add('R2.2','sl','medium','Collision theory and reaction rate',stem,correct=good,distractors=bad,reasoning=why)
for reactant,product,peak,cat in [(20,-10,95,60),(10,40,130,90),(30,-20,110,70),(15,35,105,65)]:
    B.add('R2.2','sl','medium','Reading catalysed and uncatalysed pathways','The figure gives relative enthalpy levels for two pathways of the same reaction. The vertical scale is linear. The reaction coordinate is schematic.',parts=[p('Determine the forward activation energies for the uncatalysed and catalysed pathways.',step('Subtract the reactant enthalpy from each peak enthalpy.','M1'),step('Uncatalysed: '+u(peak-reactant,r'kJ\,mol^{-1}')+'; catalysed: '+u(cat-reactant,r'kJ\,mol^{-1}')+'.')),p('Determine the reaction enthalpy and explain whether the catalyst changes it.',step('The reaction enthalpy is '+u(product-reactant,r'kJ\,mol^{-1}')+'.'),step('It is unchanged: the reactant and product states are the same for both pathways.','R1'))],diagram=profile(reactant,product,peak,cat))
for order,k,cs in [(0,.004,[.10,.20,.40]),(1,.030,[.10,.20,.40]),(2,.20,[.10,.20,.30]),(1,.080,[.05,.10,.20])]:
    rates=[k*c**order for c in cs]
    units={0:r'mol\,dm^{-3}\,s^{-1}',1:r's^{-1}',2:r'dm^3\,mol^{-1}\,s^{-1}'}[order]
    B.add('R2.2','ahl','medium','Initial rates for one reactant','A constructed initial-rate dataset is measured at constant temperature. The reaction rate depends only on the concentration of A in the range studied.\n\n'+table([r'$[\mathrm A]/\mathrm{mol\,dm^{-3}}$',r'Initial rate / $\mathrm{mol\,dm^{-3}\,s^{-1}}$'],[(f(c,6),f(rate,6)) for c,rate in zip(cs,rates)]),question_type='data-based',parts=[p('Deduce the order with respect to A and write the rate equation.',step('Compare rate factors with concentration factors at constant temperature.','M1'),step('The order is '+str(order)+r', so $r=k[\mathrm A]^{'+str(order)+'}$.')),p('Calculate the rate constant, including its units.',step('Substitution gives '+u(k,units)+'.')),p('Does the overall balanced equation alone establish this experimental order?',step('No. A rate equation is determined experimentally or from a justified mechanism; overall stoichiometric coefficients do not generally give reaction orders.','R1'))])
for a,b,k in [(1,1,.40),(2,0,.20),(0,2,.30),(1,2,.50)]:
    concentrations=[(.10,.10),(.20,.10),(.10,.20)];rates=[k*A**a*C**b for A,C in concentrations];order=a+b
    kunits=r'dm^3\,mol^{-1}\,s^{-1}' if order==2 else r'dm^6\,mol^{-2}\,s^{-1}'
    B.add('R2.2','ahl','hard','Separating two concentration effects','A constructed initial-rate study holds temperature constant. Concentrations and initial rates are:\n\n'+table([r'$[\mathrm A]/\mathrm{mol\,dm^{-3}}$',r'$[\mathrm B]/\mathrm{mol\,dm^{-3}}$',r'Rate / $\mathrm{mol\,dm^{-3}\,s^{-1}}$'],[(f(A,6),f(C,6),f(rate,6)) for (A,C),rate in zip(concentrations,rates)]),question_type='data-based',parts=[p('Determine each reactant order and the overall rate equation.',step('Trials one and two isolate A: order '+str(a)+'.','M1'),step('Trials one and three isolate B: order '+str(b)+'.','M1'),step(r'$r=k[\mathrm A]^{'+str(a)+r'}[\mathrm B]^{'+str(b)+'}$.')),p('Calculate the rate constant and predict the rate when both concentrations are 0.300 mol per cubic decimetre.',step('The rate constant is '+u(k,kunits)+'.'),step('The predicted rate is '+u(k*.3**order,r'mol\,dm^{-3}\,s^{-1}')+'.'))])
mechanisms=[(r'$\mathrm{A+B\to I}$ (slow); $\mathrm{I+B\to P}$ (fast).',r'$r=k[\mathrm A][\mathrm B]$',r'$\mathrm{A+2B\to P}$','I is produced and then consumed; the slow first step is bimolecular.'),(r'$\mathrm{A\rightleftharpoons I}$ (fast pre-equilibrium), with $[\mathrm I]=K[\mathrm A]$; $\mathrm{I+B\to P}$ (slow).',r'$r=kK[\mathrm A][\mathrm B]$',r'$\mathrm{A+B\to P}$','I is an intermediate; substitute the supplied pre-equilibrium relation into the slow-step rate.'),(r'$\mathrm{A+B\rightleftharpoons I}$ (fast pre-equilibrium), with $[\mathrm I]=K[\mathrm A][\mathrm B]$; $\mathrm{I+B\to P}$ (slow).',r'$r=kK[\mathrm A][\mathrm B]^2$',r'$\mathrm{A+2B\to P}$','I is an intermediate; the slow step depends on I and B, giving a second B factor after substitution.'),(r'$\mathrm{2A\rightleftharpoons I}$ (fast pre-equilibrium), with $[\mathrm I]=K[\mathrm A]^2$; $\mathrm{I\to P}$ (slow).',r'$r=kK[\mathrm A]^2$',r'$\mathrm{2A\to P}$','I is an intermediate; the unimolecular slow-step rate becomes second order in A after using the supplied relation.')]
for desc,rate,overall,why in mechanisms:
    B.add('R2.2','ahl','hard','Testing a proposed mechanism','A proposed abstract particle mechanism is given below. Each step is elementary. Any stated pre-equilibrium concentration relation may be used directly.\n\n'+desc,parts=[p('Identify the intermediate and write the overall equation.',step('I is formed and consumed within the mechanism.','A1'),step(overall+'.')),p('Deduce the observable rate equation and explain your reasoning.',step('Use the concentrations of the reacting species in the slow elementary step, substituting a supplied pre-equilibrium relation where required.','M1'),step(rate+'.'),step(why,'R1'))])
for Ea,T1,T2,k1 in [(75000,300,320,.002),(60000,290,310,.004),(50000,310,330,.006),(90000,300,315,.001)]:
    k2=k1*math.exp(Ea/R*(1/T1-1/T2));displayk2=float(f(k2,6));calcEa=R*math.log(displayk2/k1)/(1/T1-1/T2)
    B.add('R2.2','ahl','hard','Activation energy from two temperatures','For one reaction with an unchanged mechanism, the following constructed rate constants are measured. Assume the Arrhenius factor is constant across this range. Use '+u(R,r'J\,K^{-1}\,mol^{-1}')+'.\n\n'+table(['Temperature / K',r'$k/\mathrm{s^{-1}}$'],[(T1,f(k1,6)),(T2,f(displayk2,6))]),question_type='data-based',parts=[p('Determine the activation energy from the two temperatures.',step(r'$\ln(k_2/k_1)=E_{\mathrm a}(1/T_1-1/T_2)/R$.','M1'),step('Use absolute temperatures and rearrange for activation energy.','M1'),step('From the displayed data, the activation energy is '+u(calcEa/1000,r'kJ\,mol^{-1}')+'.')),p('State one physical factor represented by the Arrhenius factor.',step('It accounts for collision frequency and the probability of a suitable collision orientation. Accept either relevant factor.','R1'))])

# R2.3: homogeneous equilibria only; no quadratic solution is required.
eqmcq=[('Which statement describes dynamic equilibrium in a closed reacting system?','Forward and reverse reactions continue at equal rates.',['Both reactions stop permanently.','Reactant and product concentrations must be equal.','The equilibrium composition changes continuously at fixed conditions.'],'Equal rates give constant macroscopic composition, although molecular reactions continue.'),('A sealed reaction mixture reaches equilibrium at constant temperature. What follows about its concentrations?','Each concentration remains constant but the concentrations need not equal one another.',['All concentrations become identical.','Every reactant concentration becomes zero.','Every product molecule stops reacting.'],'Constancy follows from balanced forward and reverse rates, not equal amounts.'),('Why is a closed system normally required to maintain the specified chemical equilibrium?','Loss of a reacting species changes the mixture and can prevent the equilibrium composition from being maintained.',['A closed system forbids all energy transfer.','A closed system always contains equal moles of gases.','A closed system prevents reverse reactions.'],'Keeping reacting species in the system allows the forward and reverse processes to balance.'),('A catalyst is added to an equilibrium mixture at unchanged temperature. What is the expected effect?','The equilibrium composition remains unchanged, while both directions can occur faster.',['The equilibrium constant increases permanently.','Only the forward rate increases.','All reactants are immediately converted into products.'],'The catalyst changes rates for the reaction pathways without changing the equilibrium constant at fixed temperature.')]
for stem,good,bad,why in eqmcq:B.add('R2.3','sl','easy','Dynamic equilibrium',stem,correct=good,distractors=bad,reasoning=why)
equations=[(r'$\mathrm{N_2(g)+3H_2(g)\rightleftharpoons2NH_3(g)}$',r'\frac{[\mathrm{NH_3}]^2}{[\mathrm{N_2}][\mathrm{H_2}]^3}',r'\frac{[\mathrm{N_2}][\mathrm{H_2}]^3}{[\mathrm{NH_3}]^2}',r'\frac{[\mathrm{NH_3}]}{[\mathrm{N_2}][\mathrm{H_2}]}',r'[\mathrm{NH_3}]^2[\mathrm{N_2}][\mathrm{H_2}]^3'),(r'$\mathrm{H_2(g)+I_2(g)\rightleftharpoons2HI(g)}$',r'\frac{[\mathrm{HI}]^2}{[\mathrm{H_2}][\mathrm{I_2}]}',r'\frac{[\mathrm{H_2}][\mathrm{I_2}]}{[\mathrm{HI}]^2}',r'\frac{[\mathrm{HI}]}{[\mathrm{H_2}][\mathrm{I_2}]}',r'[\mathrm{HI}]^2[\mathrm{H_2}][\mathrm{I_2}]'),(r'$\mathrm{2SO_2(g)+O_2(g)\rightleftharpoons2SO_3(g)}$',r'\frac{[\mathrm{SO_3}]^2}{[\mathrm{SO_2}]^2[\mathrm{O_2}]}',r'\frac{[\mathrm{SO_2}]^2[\mathrm{O_2}]}{[\mathrm{SO_3}]^2}',r'\frac{[\mathrm{SO_3}]}{[\mathrm{SO_2}][\mathrm{O_2}]}',r'[\mathrm{SO_3}]^2[\mathrm{SO_2}]^2[\mathrm{O_2}]'),(r'$\mathrm{PCl_5(g)\rightleftharpoons PCl_3(g)+Cl_2(g)}$',r'\frac{[\mathrm{PCl_3}][\mathrm{Cl_2}]}{[\mathrm{PCl_5}]}',r'\frac{[\mathrm{PCl_5}]}{[\mathrm{PCl_3}][\mathrm{Cl_2}]}',r'\frac{[\mathrm{PCl_3}]+[\mathrm{Cl_2}]}{[\mathrm{PCl_5}]}',r'[\mathrm{PCl_3}][\mathrm{Cl_2}][\mathrm{PCl_5}]')]
for equation,good,*bad in equations:B.add('R2.3','sl','medium','An equilibrium expression',equation+'. Which expression is the concentration equilibrium constant for this homogeneous system?',correct='$'+good+'$',distractors=['$'+z+'$' for z in bad],reasoning='Use product concentrations over reactant concentrations, each raised to its stoichiometric coefficient. Do not add concentrations.')
for K in [4,25,.20,10]:
    B.add('R2.3','sl','medium','Reversing an equilibrium equation',f'For a homogeneous reaction written in the forward direction, the equilibrium constant is {f(K)} at a specified temperature. What is the constant for the exactly reversed equation at the same temperature?',correct='$'+v(1/K)+'$',distractors=['$'+v(K)+'$','$'+v(-K)+'$','$'+v(K*K)+'$'],reasoning='Reversing the equation exchanges the numerator and denominator of the equilibrium expression, so the new constant is the reciprocal.')
for equation,dh,gaschange in [(equations[0][0],-92,-2),(r'$\mathrm{2NO_2(g)\rightleftharpoons N_2O_4(g)}$',-57,-1),(equations[1][0],-10,0),(equations[3][0],87,1)]:
    pressure='towards products' if gaschange<0 else ('towards reactants' if gaschange>0 else 'neither way')
    heat='towards reactants' if dh<0 else 'towards products'
    B.add('R2.3','sl','medium','Disturbing a gaseous equilibrium',equation+' has forward enthalpy change '+u(dh,r'kJ\,mol^{-1}')+'. The gases are initially at equilibrium. Consider each disturbance separately.',parts=[p('Predict the effect of decreasing the container volume at constant temperature.',step('The equilibrium shifts '+pressure+('. Both sides have equal gas mole totals.' if gaschange==0 else ' because the favoured side has fewer moles of gas.'),'R1')),p('Predict the effect of increasing temperature, including the direction of change in the equilibrium constant.',step('The equilibrium shifts '+heat+'; increasing temperature favours the endothermic direction.','R1'),step(('The forward equilibrium constant decreases.' if dh<0 else 'The forward equilibrium constant increases.'),'R1')),p('State the effect of a catalyst on the equilibrium amount of product at unchanged temperature.',step('There is no change in equilibrium composition; a catalyst accelerates approach to equilibrium.','R1'))])
for A,C,P,K in [(.20,.30,.20,4),(.10,.10,.40,4),(.40,.25,.20,2),(.20,.20,.60,3)]:
    Q=P*P/(A*C)
    B.add('R2.3','ahl','medium','Reaction quotient and direction',equations[1][0]+f'. At a fixed temperature, the equilibrium constant is {f(K)}. A mixture has hydrogen, iodine and hydrogen iodide concentrations '+u(A,r'mol\,dm^{-3}')+', '+u(C,r'mol\,dm^{-3}')+' and '+u(P,r'mol\,dm^{-3}')+' respectively.',parts=[p('Calculate the reaction quotient and predict the initial net direction of change.',step(r'$Q_{\mathrm c}=[\mathrm{HI}]^2/([\mathrm{H_2}][\mathrm{I_2}])$.','M1'),step('The reaction quotient is '+f(Q)+'.'),step(('Since the quotient is below the equilibrium constant, the forward reaction predominates initially.' if Q<K else 'Since the quotient exceeds the equilibrium constant, the reverse reaction predominates initially.'),'R1'))])
for c,K in [(.50,4),(.40,9),(.60,.25),(.30,.50)]:
    eqA=c/(1+K);eqB=c-eqA
    B.add('R2.3','ahl','hard','A linear equilibrium calculation',r'Two gaseous isomers interconvert by the model equation $\mathrm{A(g)\rightleftharpoons B(g)}$. Initially only A is present at concentration '+u(c,r'mol\,dm^{-3}')+f'. At the stated temperature, '+r'$K_{\mathrm c}=[\mathrm B]/[\mathrm A]=$ '+f(K)+'. Volume is constant.',question_type='data-based',parts=[p('Set up and solve the equilibrium concentration expression.',step('If the concentration converted is x, equilibrium concentrations are initial A minus x, and x for B.','M1'),step(r'$K_{\mathrm c}=x/(c_0-x)$, which is a linear equation after rearrangement.','M1'),step('The A concentration is '+u(eqA,r'mol\,dm^{-3}')+' and the B concentration is '+u(eqB,r'mol\,dm^{-3}')+'.')),p('Check your result against the supplied equilibrium constant.',step('The ratio of B to A reproduces '+f(K)+' before rounding.','R1'))])
for c,K in [(.20,1e-6),(.25,1e-5),(.50,4e-6),(.36,9e-6)]:
    x=math.sqrt(c*K);pc=100*x/c
    B.add('R2.3','ahl','hard','Checking a small-change approximation',r'$\mathrm{SO_2Cl_2(g)\rightleftharpoons SO_2(g)+Cl_2(g)}$. Initially only sulfuryl chloride is present at concentration '+u(c,r'mol\,dm^{-3}')+'. At the stated temperature, the numerical concentration equilibrium constant is $'+v(K)+'$ when concentrations are substituted in '+r'$\mathrm{mol\,dm^{-3}}$'+'. Use the small-change approximation; solving a quadratic equation is not required.',parts=[p('Set up the equilibrium expression and estimate both product concentrations.',step(r'If each product concentration is x, $K_{\mathrm c}=x^2/(c_0-x)$.','M1'),step(r'For a small change, $c_0-x\approx c_0$, so $x\approx\sqrt{K_{\mathrm c}c_0}$.','M1'),step('Each product concentration is approximately '+u(x,r'mol\,dm^{-3}')+'.')),p('Calculate the fraction of the initial reactant consumed and assess the approximation.',step('About '+u(pc,r'\%')+' is consumed.'),step('This is a small fraction of the initial concentration, supporting the approximation that the reactant concentration remains close to its initial value.','R1'))])
for K1,K2 in [(25,5),(.10,.40),(100,40),(.50,2)]:
    G=-R*300*math.log(K1)/1000
    B.add('R2.3','ahl','hard','Temperature-dependent equilibrium data','A constructed model supplies dimensionless thermodynamic equilibrium constants for one unchanged reaction. Assume no phase or mechanism change over this temperature interval.\n\n'+table(['Temperature / K','Equilibrium constant'],[(300,K1),(350,K2)])+'\n\nUse '+u(R,r'J\,K^{-1}\,mol^{-1}')+'.',question_type='data-based',parts=[p('Deduce whether the forward reaction is exothermic or endothermic.',step(('The equilibrium constant decreases as temperature rises, so the forward reaction is exothermic.' if K2<K1 else 'The equilibrium constant increases as temperature rises, so the forward reaction is endothermic.'),'R1')),p('Calculate the standard Gibbs energy change at 300 K.',step(r'$\Delta G^\circ=-RT\ln K$.','M1'),step('The standard Gibbs energy change is '+u(G,r'kJ\,mol^{-1}')+'.')),p('Does the sign of the standard Gibbs energy by itself establish the spontaneous direction for every possible starting composition?',step('No. Actual Gibbs energy also depends on the reaction quotient; compare the current composition with the equilibrium composition.','R1'))])
for question in B.questions:
    if question['questionType']=='data-based' and not any(word in question['stem'].lower() for word in ('constructed','model')):
        question['stem']='The following data are constructed for this question. '+question['stem']
B.write(96)
